"""Solidity ABI 值层编解码。

遵循 Solidity ABI 的 head/tail 布局：

- 静态类型直接占用一个或多个 32 字节字；
- 动态类型（string / 动态 bytes / 动态数组 / 含动态成员的定长数组
  或元组）在 head 中放 32 字节偏移，实体置于 tail；
- 动态数组实体以长度字开头，随后是与“等长定长数组”相同的块；
- 偏移均相对于所属块（数组元素块的起点在长度字之后）。

解码采用严格规范：块内动态成员必须按声明顺序紧密排列（偏移恰好指向前
一动态实体的终点），不允许空洞、重叠或倒序；所有填充字节必须为零。

值口径：
- uintM/intM -> int，bool -> bool，string -> str；
- bytes/bytesM -> bytes；
- fixedMxN/ufixedMxN -> decimal.Decimal（解码结果小数位数恰为 N）；
- function -> 24 字节 bytes（20 字节地址 + 4 字节 selector）；
- address -> 小写 ``"0x" + 40 个十六进制字符``；
- 数组 -> list，元组 -> tuple。

所有值不匹配、非法编码与不适用的类型对象统一抛出
:class:`abi_kit.ABIValueError`；类型层错误仍属
:class:`abi_kit.ABITypeError`，本模块不改变其适用范围。
"""

from __future__ import annotations

from decimal import Decimal

from ._exceptions import ABIValueError
from ._types import (
    ABIType,
    ArrayType,
    ElementaryType,
    FixedPointType,
    FunctionType,
    FUNCTION_BYTE_SIZE,
    TupleType,
)

_WORD = 32


# ---- 类型静态性质 --------------------------------------------------------


def _is_dynamic(abi_type: ABIType) -> bool:
    if isinstance(abi_type, ElementaryType):
        return abi_type.kind == "string" or (
            abi_type.kind == "bytes" and abi_type.byte_size is None
        )
    if isinstance(abi_type, (FixedPointType, FunctionType)):
        return False
    if isinstance(abi_type, ArrayType):
        return abi_type.length is None or _is_dynamic(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return any(_is_dynamic(c) for c in abi_type.components)
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _static_size(abi_type: ABIType) -> int:
    """静态类型作为一个整体占用的字节数（仅对非动态类型调用）。"""
    if isinstance(abi_type, ElementaryType):
        return _WORD
    if isinstance(abi_type, (FixedPointType, FunctionType)):
        return _WORD
    if isinstance(abi_type, ArrayType):
        return abi_type.length * _static_size(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return sum(_static_size(c) for c in abi_type.components)
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


def _head_slot(abi_type: ABIType) -> int:
    """该类型作为块成员时在 head 中占用的字节数。"""
    return _WORD if _is_dynamic(abi_type) else _static_size(abi_type)


# ---- 编码 ----------------------------------------------------------------


def _uint_word(value: int) -> bytes:
    return value.to_bytes(_WORD, "big", signed=False)


def _address_bytes(value) -> bytes:
    if not isinstance(value, str):
        raise ABIValueError(f"address 需要十六进制字符串，得到 {type(value).__name__}")
    text = value[2:] if value.startswith(("0x", "0X")) else value
    if len(text) != 40 or any(c not in "0123456789abcdefABCDEF" for c in text):
        raise ABIValueError(
            f"address 必须是带或不带 0x 前缀的 40 位十六进制字符串：{value!r}"
        )
    return bytes.fromhex(text)


def _len_prefixed(payload: bytes) -> bytes:
    padding = (-len(payload)) % _WORD
    return _uint_word(len(payload)) + payload + b"\x00" * padding


def _fixed_scaled(t: FixedPointType, value: Decimal) -> int:
    """把 Decimal 校验并缩放为整数 ``value * 10**N``。"""
    if not isinstance(value, Decimal):
        raise ABIValueError(
            f"{'u' if not t.signed else ''}fixed{t.bit_size}x{t.scale} "
            f"需要 decimal.Decimal，得到 {type(value).__name__}"
        )
    if not value.is_finite():
        raise ABIValueError("fixed 值必须有限，不接受 NaN 或 Infinity")
    # 有效小数位即 Decimal 指数的绝对值；Decimal('1.250') 为 3 位。
    sign, digits, exponent = value.as_tuple()
    fractional = max(0, -exponent)
    if fractional > t.scale:
        raise ABIValueError(
            f"fixed{t.bit_size}x{t.scale} 至多接受 {t.scale} 位小数，"
            f"得到 {fractional} 位：{value}"
        )
    # 直接由十进制数字与指数构造缩放整数 sign * digits * 10**(exponent+N)。

        else:
            member_types = []
        values, end = _decode_block(member_types, data, base, bound)
        return values, end
    if isinstance(abi_type, TupleType):
        values, end = _decode_block(list(abi_type.components), data, pos, bound)
        return tuple(values), end
    raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")


# ---- 公开入口 ------------------------------------------------------------


def encode_abi_value(abi_type: ABIType, value) -> bytes:
    """按 ``abi_type`` 把 Python 值编码为完整 ABI 编码 bytes。

    值与类型不匹配或类型对象不适用时抛出 :class:`abi_kit.ABIValueError`。
    """
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")
    return _encode(abi_type, value)


def decode_abi_value(abi_type: ABIType, data: bytes):
    """把完整 ABI 编码 bytes 解码回 Python 值。

    要求 ``data`` 恰好容纳一个值：长度不足、偏移越界、尾部残留、
    定长数组长度不符、非法布尔字、非法 UTF-8 或越界数值均抛出
    :class:`abi_kit.ABIValueError`。
    """
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"无法编解码非 ABIType 对象：{abi_type!r}")
    if not isinstance(data, bytes):
        raise ABIValueError(f"编码数据必须是 bytes，得到 {type(data).__name__}")

    bound = len(data)
    value, end = _decode(abi_type, data, 0, bound)
    if end != bound:
        raise ABIValueError(
            f"尾部残留 {bound - end} 字节：编码未被完整消费"
        )
    return value

"""嵌套值的路径化读取与定点替换。

在完整值编解码（:mod:`abi_kit._codec`）之上提供两个面向调用方的入口：

- :func:`get_abi_value_at_path`：按 ABI 类型、完整编码字节与路径，只返回
  路径选中的子值；
- :func:`replace_abi_value_at_path`：在相同类型与原始编码下，用替换值
  定点替换路径所指子值，返回整体重新编码后的全新字节。原字节不会被就地
  修改；动态偏移与长度随结果重新计算，替换前后动态数据长度不同也不会
  影响未选中的兄弟节点。
- :func:`replace_abi_values_at_paths`：在同一份原始编码上，按顺序给出
  多条（路径, 新值）对，一次调用原子替换多个互不重叠的子值，统一重算
  动态偏移、数组长度与内层布局；替换序列为空时返回与输入内容相同的新
  bytes。同一路径重复或两条路径互为祖先与后代时，整次操作以
  ``PATH_CONFLICT`` 拒绝。

路径语法：

- 点号 ``.`` 连接 tuple 字段名，字段名匹配类型中声明的名称；
- 方括号内的非负十进制数字（从 0 开始）选择数组元素，也可按位置选择
  tuple 元素；
- 空路径表示整个根值；
- 不接受空段、空字段名、负数、带符号或带空格索引及多余分隔符。

tuple 字段名通过两种方式提供：直接构造带 ``names`` 的
:class:`abi_kit.TupleType`，或向本模块传入 Solidity 声明风格的类型字符串
（组件类型后可空白跟一个字段名），例如::

    (uint256 amount,(address to,uint256 value)[] items)

该带名语法仅用于本模块，:func:`abi_kit.parse_abi_type` 的严格规范语法保持
不变。

七类失败统一抛出带唯一错误码的 :class:`abi_kit.AbiPathError`：

- ``PATH_SYNTAX`` / ``PATH_OUT_OF_RANGE`` / ``PATH_NOT_FOUND`` /
  ``PATH_TYPE_MISMATCH`` / ``PATH_VALUE_MISMATCH`` /
  ``PATH_REPLACEMENTS_INVALID`` / ``PATH_CONFLICT``。

原始编码本身非法时仍按值层约定抛出 :class:`abi_kit.ABIValueError`，不属于
上述五类路径失败。
"""

from __future__ import annotations

from ._codec import _encode, decode_abi_value
from ._exceptions import ABITypeError, ABIValueError, AbiPathError
from ._types import (
    ABIType,
    ArrayType,
    ElementaryType,
    FixedPointType,
    FunctionType,
    TupleType,
)

_WHITESPACE = " \t\n\r\f\v"
_NAME_START = set(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_$"
)
_NAME_PART = _NAME_START | set("0123456789")

PATH_SYNTAX = "PATH_SYNTAX"
PATH_OUT_OF_RANGE = "PATH_OUT_OF_RANGE"
PATH_NOT_FOUND = "PATH_NOT_FOUND"
PATH_TYPE_MISMATCH = "PATH_TYPE_MISMATCH"
PATH_VALUE_MISMATCH = "PATH_VALUE_MISMATCH"
PATH_REPLACEMENTS_INVALID = "PATH_REPLACEMENTS_INVALID"
PATH_CONFLICT = "PATH_CONFLICT"


# ---- 带字段名的类型字符串 -------------------------------------------------


class _NamedParser:
    """解析带可选组件名的类型字符串（Solidity 声明风格）。

    与 :func:`abi_kit.parse_abi_type` 使用同一套类型校验（构造相同的不可变
    类型对象），区别仅在于 tuple 组件后允许空白跟一个字段名。
    """

    _RECURSION_SAFETY_LIMIT = 200

    def __init__(self, text: str) -> None:
        self._text = text
        self._pos = 0
        self._len = len(text)
        self._tuple_depth = 0

    def _error(self, message: str) -> ABITypeError:
        return ABITypeError(
            f"无效的 ABI 类型 {self._text!r}（位置 {self._pos}）：{message}"
        )

    def _skip_whitespace(self) -> None:
        text = self._text
        while self._pos < self._len and text[self._pos] in _WHITESPACE:
            self._pos += 1

    def _peek(self) -> str | None:
        if self._pos >= self._len:
            return None
        return self._text[self._pos]

    def parse(self) -> ABIType:
        self._skip_whitespace()
        result = self._parse_type()
        self._skip_whitespace()
        if self._pos != self._len:
            raise self._error("存在无法解析的尾随内容")
        return result

    def _parse_type(self) -> ABIType:
        ch = self._peek()
        if ch is None:
            raise self._error("类型不完整")
        if ch == "(":
            head: ABIType = self._parse_tuple()
        elif ch in _NAME_START:
            head = self._parse_elementary()
        else:
            raise self._error("此处应为基础类型或元组")
        return self._parse_suffixes(head)

    def _parse_elementary(self) -> ABIType:
        text = self._text
        start = self._pos
        while self._pos < self._len:
            ch = text[self._pos]
            if ch.isascii() and ch.isalnum():
                self._pos += 1
            else:
                break
        word = text[start:self._pos]
        if word in ("address", "bool", "string", "bytes"):
            return ElementaryType(word)
        if word == "function":
            return FunctionType()
        if word.startswith("bytes") and len(word) > len("bytes"):
            digits = self._digits(word, "bytes")
            try:
                return ElementaryType("bytes", byte_size=int(digits))
            except ABITypeError:
                raise self._error(
                    f"bytesM 的 M 必须在 1 到 32 之间，得到 {digits}"
                ) from None
        if word.startswith(("ufixed", "fixed")):
            if word.startswith("ufixed"):
                prefix, signed = "ufixed", False
            else:
                prefix, signed = "fixed", True
            rest = word[len(prefix):]
            parts = rest.split("x")
            if (
                len(parts) != 2
                or not parts[0]
                or not parts[1]
                or not all(p.isascii() and p.isdigit() for p in parts)
            ):
                raise self._error(f"不是合法的基础类型：{word!r}")
            m_digits, n_digits = parts
            if (len(m_digits) > 1 and m_digits[0] == "0") or (
                len(n_digits) > 1 and n_digits[0] == "0"
            ):
                raise self._error(f"类型宽度不允许前导零：{word!r}")
            bit_size, scale = int(m_digits), int(n_digits)
            try:
                return FixedPointType(signed, bit_size, scale)
            except ABITypeError:
                raise self._error(
                    f"{prefix} 的 M 必须是 8 到 256 之间 8 的倍数、N 必须在 1 到 "
                    f"80 之间，得到 {bit_size}x{scale}"
                ) from None
        if word.startswith("uint") or word.startswith("int"):
            kind = "uint" if word.startswith("uint") else "int"
            prefix = kind
            digits = self._digits(word, prefix)
            try:
                return ElementaryType(kind, bit_size=int(digits))
            except ABITypeError:
                raise self._error(
                    f"{kind} 的位宽必须是 8 到 256 之间 8 的倍数，得到 {digits}"
                ) from None
        raise self._error(f"不是合法的基础类型：{word!r}")

    def _digits(self, word: str, prefix: str) -> str:
        digits = word[len(prefix):]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise self._error(f"不是合法的基础类型：{word!r}")
        if len(digits) > 1 and digits[0] == "0":
            raise self._error(f"类型宽度不允许前导零：{word!r}")
        return digits

    def _parse_tuple(self) -> TupleType:
        self._pos += 1
        self._tuple_depth += 1
        if self._tuple_depth > self._RECURSION_SAFETY_LIMIT:
            self._tuple_depth -= 1
            raise self._error("类型嵌套过深或括号未正确闭合")
        try:
            self._skip_whitespace()
            if self._peek() == ")":
                self._pos += 1
                return TupleType(())
            component_types: list[ABIType] = []
            component_names: list[str | None] = []
            while True:
                component_types.append(self._parse_type())
                self._skip_whitespace()
                component_names.append(self._read_optional_name())
                self._skip_whitespace()
                ch = self._peek()
                if ch == ",":
                    self._pos += 1
                    self._skip_whitespace()
                    if self._peek() in (None, ",", ")"):
                        raise self._error("逗号后缺少类型")
                    continue
                if ch == ")":
                    self._pos += 1
                    names = (
                        tuple(component_names)
                        if any(name is not None for name in component_names)
                        else None
                    )
                    return TupleType(tuple(component_types), names)
                raise self._error("元组中应为 ',' 或 ')'")
        finally:
            self._tuple_depth -= 1

    def _read_optional_name(self) -> str | None:
        """读取紧跟在组件类型之后的可选字段名；调用前已跳过空白。"""
        ch = self._peek()
        if ch is None or ch not in _NAME_START:
            return None
        start = self._pos
        self._pos += 1
        while self._pos < self._len and self._text[self._pos] in _NAME_PART:
            self._pos += 1
        name = self._text[start:self._pos]
        self._skip_whitespace()
        if self._peek() not in (",", ")", None):
            raise self._error(f"字段名 {name!r} 后应为 ',' 或 ')'")
        return name

    def _parse_suffixes(self, head: ABIType) -> ABIType:
        current = head
        while self._peek() == "[":
            self._pos += 1
            ch = self._peek()
            if ch is None:
                raise self._error("数组后缀不完整")
            if ch == "]":
                self._pos += 1
                current = ArrayType(current)
                continue
            if not (ch.isascii() and ch.isdigit()) or ch == "0":
                raise self._error("数组长度必须是无前导零的正整数")
            start = self._pos
            while self._pos < self._len:
                ch = self._text[self._pos]
                if ch.isascii() and ch.isdigit():
                    self._pos += 1
                    continue
                break
            length = int(self._text[start:self._pos])
            if self._peek() != "]":
                raise self._error("数组后缀缺少 ']'")
            self._pos += 1
            current = ArrayType(current, length)
        return current


def _coerce_type(abi_type: ABIType | str) -> ABIType:
    if isinstance(abi_type, ABIType):
        return abi_type
    if isinstance(abi_type, str):
        return _NamedParser(abi_type).parse()
    raise ABITypeError(
        f"ABI 类型必须是 ABIType 或类型字符串，得到 {type(abi_type).__name__}"
    )


def _coerce_data(data: bytes | str) -> bytes:
    if isinstance(data, bytes):
        return data
    if isinstance(data, str):
        text = data[2:] if data[:2] in ("0x", "0X") else data
        try:
            return bytes.fromhex(text)
        except ValueError as exc:
            raise ABIValueError(f"编码十六进制字节非法：{exc}") from exc
    raise ABIValueError(
        f"编码数据必须是 bytes 或十六进制 str，得到 {type(data).__name__}"
    )


